struct BinaryTrie {
	typedef unsigned U;
	BinaryTrie *nxt[2];
	U size = 0;
	BinaryTrie() { nxt[0] = nxt[1] = 0; }
	bool insert(U x, int ind = 31) {
		if (ind < 0) {
			if (size == 0) return (size = 1);
			return false;
		}
		int bit = (x >> ind) & 1;
		if (!nxt[bit]) nxt[bit] = new BinaryTrie();
		bool res = nxt[bit]->insert(x, ind - 1);
		size += res;
		return res;
	}
	U mex(U xr, U cur = 0, int ind = 31) {
		if (ind < 0) return cur;
		int bit = (xr >> ind) & 1;
		if (nxt[bit] && nxt[bit]->size == (1u << ind)) {
			if (nxt[!bit])
				return nxt[!bit]->mex(xr, cur | (1u << ind),
					ind - 1);
			return cur | (1u << ind);
		} else if (nxt[bit])
			return nxt[bit]->mex(xr, cur, ind - 1);
		return cur;
	}
	U maxxor(U xr, U cur = 0, int ind = 31) {
		if (ind < 0) return cur;
		int bit = (xr >> ind) & 1;
		if (nxt[!bit])
			return nxt[!bit]->maxxor(xr, cur | (1u << ind),
				ind - 1);
		if (nxt[bit])
			return nxt[bit]->maxxor(xr, cur, ind - 1);
		return cur;
	}
	~BinaryTrie() { delete nxt[0]; delete nxt[1]; }
};

struct FT {
	vector<ll> s;
	FT(int n) : s(n) {}
	void update(int pos, ll dif) { // a[pos] += dif
		for (; pos < sz(s); pos |= pos + 1) s[pos] += dif;
	}
	ll query(int pos) { // sum of values in [0, pos)
		ll res = 0;
		for (; pos > 0; pos &= pos - 1) res += s[pos-1];
		return res;
	}
	int lower_bound(ll sum) {// min pos st sum of [0, pos] >= sum
		// Returns n if no sum is >= sum, or -1 if empty sum is.
		if (sum <= 0) return -1;
		int pos = 0;
		for (int pw = 1 << 25; pw; pw >>= 1) {
			if (pos + pw <= sz(s) && s[pos + pw-1] < sum)
				pos += pw, sum -= s[pos-1];
		}
		return pos;
	}
};

struct FT2 {
	vector<vi> ys; vector<FT> ft;
	FT2(int limx) : ys(limx) {}
	void fakeUpdate(int x, int y) {
		for (; x < sz(ys); x |= x + 1) ys[x].push_back(y);
	}
	void init() {
		for (vi& v : ys) sort(all(v)), ft.emplace_back(sz(v));
	}
	int ind(int x, int y) {
		return (int)(lower_bound(all(ys[x]), y) - ys[x].begin()); }
	void update(int x, int y, ll dif) {
		for (; x < sz(ys); x |= x + 1)
			ft[x].update(ind(x, y), dif);
	}
	ll query(int x, int y) {
		ll sum = 0;
		for (; x; x &= x - 1)
			sum += ft[x-1].query(ind(x-1, y));
		return sum;
	}
};

